  <script>
    // reveal
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion:reduce)').matches;
      const els = document.querySelectorAll('[data-reveal]');
      if(reduced){ els.forEach(e=>e.classList.add('visible')); return; }
      const io=new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.08});
      els.forEach(el=>io.observe(el));
    })();

    // mock events module
    (function(){
      const next = {title:'Evening Resonance',date:addDays(3),time:'6:30 PM',location:'Studio'};
