      function addDays(n){ const d=new Date(); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); }
      document.getElementById('nextEvent').innerHTML = '<strong>'+next.title+'</strong><div style="color:var(--muted)">'+next.date+' • '+next.time+' • '+next.location+'</div><div style="margin-top:8px"><a href="events.html" class="btn" style="background:#6a4b2d">See all events</a></div>';
      const ul=document.getElementById('calendarList'); list.forEach(date=>{ const li=document.createElement('li'); li.textContent = date + ' — Public seat'; ul.appendChild(li); });
    })();

    // booking form handler (local demo)
    (function(){
      const form=document.getElementById('bookingForm');
      form.addEventListener('submit',(e)=>{
        e.preventDefault();
        const name=form.name.value.trim();
        const email=form.email.value.trim();
        const service=form.service.value;
        const contra = document.getElementById('contraCheck').checked;
        const res=document.getElementById('result');
        if(!name||!email){ res.textContent='Please provide name and email.'; return; }
        if(!contra){ res.textContent='Please acknowledge the contraindications to continue.'; return; }
        // mock response
        if(service==='vip'){
          res.innerHTML = 'Thanks, '+name+'. We received your VIP Day inquiry. We will follow up at '+email+' to coordinate dates and pricing.';
        } else {
          res.innerHTML = 'Thanks, '+name+'. Your request is noted. We will confirm availability via email within 48 hours.';
        }
        form.reset();
      });
    })();
  </script>
